using System;
using System.Reflection;
using System.Threading;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

[AttributeUsage(AttributeTargets.Method, AllowMultiple = false)]
public sealed class TimedTestMethodAttribute : Attribute
{
    public int WarningThresholdMs { get; }

    public TimedTestMethodAttribute(int warningThresholdMs = 5000)
    {
        WarningThresholdMs = warningThresholdMs;
    }
}

[TestClass]
public abstract class TimedTestBase
{
    private System.Diagnostics.Stopwatch? _stopwatch;
    private int _warningThresholdMs;

    [TestInitialize]
    public void TimedTestInitialize()
    {
        var method = GetType().GetMethod(
            TestContext!.TestName!,
            BindingFlags.Public | BindingFlags.Instance);

        var attr = method?.GetCustomAttribute<TimedTestMethodAttribute>();
        if (attr != null)
        {
            _warningThresholdMs = attr.WarningThresholdMs;
            _stopwatch = System.Diagnostics.Stopwatch.StartNew();
        }
    }

    [TestCleanup]
    public void TimedTestCleanup()
    {
        if (_stopwatch != null)
        {
            _stopwatch.Stop();
            if (_stopwatch.ElapsedMilliseconds > _warningThresholdMs)
            {
                Console.WriteLine($"WARNING: {TestContext!.TestName} took {_stopwatch.ElapsedMilliseconds}ms (threshold: {_warningThresholdMs}ms)");
            }
        }
    }

    public TestContext? TestContext { get; set; }
}

